<template>
  <div class="pr-page">
    <header class="pr-header">
      <div><h2>Bảng lương tháng {{ monthLabel }}</h2><p>Quản lý thu nhập, công, tăng ca và khấu trừ của nhân viên</p></div>
      <div class="pr-header-actions">
        <div class="pr-month-nav"><button aria-label="Tháng trước" @click="moveMonth(-1)"><v-icon icon="mdi-chevron-left" /></button><v-icon icon="mdi-calendar-month-outline" size="18"/><strong>Tháng {{ monthLabel }}</strong><button aria-label="Tháng sau" @click="moveMonth(1)"><v-icon icon="mdi-chevron-right" /></button></div>
        <v-btn variant="outlined" prepend-icon="mdi-file-excel-outline" :disabled="!filteredRows.length" :loading="exporting" @click="exportExcel">Xuất Excel</v-btn>
      </div>
    </header>

    <section class="pr-stats" aria-label="Thống kê bảng lương">
      <article v-for="item in statItems" :key="item.key" :class="`tone-${item.tone}`"><span><v-icon :icon="item.icon" size="21"/></span><div><small>{{item.label}}</small><strong>{{item.value}}</strong></div></article>
    </section>

    <section class="pr-toolbar">
      <label class="pr-search"><v-icon icon="mdi-magnify" size="20"/><input v-model="search" placeholder="Tìm tên hoặc email nhân viên..."/><button v-if="search" aria-label="Xóa tìm kiếm" @click="search=''"><v-icon icon="mdi-close" size="17"/></button></label>
      <div class="pr-formula"><v-icon icon="mdi-calculator-variant-outline" size="18"/><span>Thực nhận = Tổng thu nhập − Tạm ứng − Đền đơn − Bảo hiểm</span></div>
      <span class="pr-count">{{filteredRows.length}} / {{rows.length}} nhân viên</span>
    </section>

    <div v-if="loadError" class="pr-error"><v-icon icon="mdi-cloud-alert-outline"/><div><strong>Không tải được bảng lương</strong><span>{{loadError}}</span></div><v-btn color="primary" variant="tonal" @click="load">Thử lại</v-btn></div>

    <section class="pr-table-card">
      <div v-if="loading&&!rows.length" class="pr-loading"><i v-for="i in 5" :key="i"/></div>
      <div v-else-if="filteredRows.length" class="pr-table-wrap">
        <table>
          <colgroup><col style="width:42px"><col style="width:200px"><col style="width:120px"><col style="width:115px"><col style="width:120px"><col style="width:100px"><col style="width:115px"><col style="width:95px"><col style="width:95px"><col style="width:125px"><col style="width:130px"><col style="width:115px"><col style="width:95px"><col style="width:76px"></colgroup>
          <thead><tr><th>#</th><th>Nhân viên</th><th>Lương cơ bản</th><th>Ngày công</th><th>Lương theo công</th><th>Tăng ca</th><th>Tiền tăng ca</th><th>KPI</th><th>Phụ cấp</th><th>Tổng thu nhập</th><th>Khấu trừ</th><th>Thực nhận</th><th>Trạng thái</th><th></th></tr></thead>
          <tbody>
            <tr v-for="(item,index) in filteredRows" :key="item.user.id">
              <td class="pr-index">{{index+1}}</td>
              <td><div class="pr-employee"><span>{{initials(item.user?.fullName||item.user?.email)}}</span><div><strong>{{item.user?.fullName||item.user?.email}}</strong><small>{{item.user?.email||'—'}}</small><em v-if="item.record.hasInsurance"><v-icon icon="mdi-shield-check-outline" size="13"/>Có bảo hiểm</em></div></div></td>
              <td class="money">{{formatVnd(item.record.baseSalary)}}</td>
              <td><div class="pr-workdays"><strong>{{item.record.workDays}}</strong><span>/ {{item.record.workingDays||26}} công</span><i><b :style="{width:workPercent(item.record)+'%'}"/></i></div></td>
              <td class="money">{{formatVnd(item.record.thanhTien)}}</td>
              <td><div class="pr-overtime"><strong>{{item.record.overtimeHours||0}}h <small>150%</small></strong><span>{{item.record.overtimeSundayHours||0}}h CN <small>200%</small></span></div></td>
              <td class="money pr-ot-money">{{formatVnd(item.record.overtimeAmount)}}</td>
              <td class="money pr-positive">{{formatVnd(item.record.kpiAmount)}}</td>
              <td class="money pr-allowance">{{formatVnd(item.record.allowanceAmount)}}</td>
              <td class="money"><strong>{{formatVnd(item.record.totalSalary)}}</strong></td>
              <td><div class="pr-deduction"><strong>{{formatVnd(totalDeduction(item.record))}}</strong><span>Ứng {{formatVnd(item.record.advanceAmount)}}</span></div></td>
              <td class="money pr-net">{{formatVnd(item.record.netSalary)}}</td>
              <td><span class="pr-status" :class="item.record.isManualOverride?'manual':'auto'"><v-icon :icon="item.record.isManualOverride?'mdi-pencil-outline':'mdi-calculator-variant-outline'" size="14"/>{{item.record.isManualOverride?'Đã nhập':'Tự tính'}}</span></td>
              <td><div class="pr-row-actions"><button title="Xem phiếu lương" @click="viewSlip(item)"><v-icon icon="mdi-eye-outline" size="19"/></button><button v-if="canEdit" title="Chỉnh sửa lương" @click="openEdit(item)"><v-icon icon="mdi-pencil-outline" size="19"/></button></div></td>
            </tr>
          </tbody>
          <tfoot><tr><td colspan="2">TỔNG CỘNG</td><td>{{formatVnd(totals.baseSalary)}}</td><td>{{totals.workDays}} công</td><td>{{formatVnd(totals.thanhTien)}}</td><td>{{totals.overtimeHours}}h / {{totals.overtimeSundayHours}}h CN</td><td>{{formatVnd(totals.overtimeAmount)}}</td><td>{{formatVnd(totals.kpiAmount)}}</td><td>{{formatVnd(totals.allowanceAmount)}}</td><td>{{formatVnd(totals.totalSalary)}}</td><td>{{formatVnd(totals.deduction)}}</td><td class="pr-net">{{formatVnd(totals.netSalary)}}</td><td colspan="2"></td></tr></tfoot>
        </table>
      </div>
      <div v-else class="pr-empty"><span><v-icon icon="mdi-account-cash-outline" size="34"/></span><h3>{{search?'Không tìm thấy nhân viên':'Chưa có dữ liệu bảng lương'}}</h3><p>{{search?'Thử tên hoặc email khác.':'Dữ liệu sẽ được tính từ chấm công và cấu hình lương.'}}</p><v-btn v-if="search" color="primary" variant="tonal" @click="search=''">Xóa tìm kiếm</v-btn></div>
    </section>
    <p class="pr-hint">Cuộn ngang để xem đủ cột. Dùng nút bút chì để chỉnh chi tiết lương.</p>

    <v-dialog v-model="editDialog" max-width="760" persistent scrollable>
      <v-card v-if="editing" class="pr-edit-dialog">
        <header><span>{{initials(editing.user?.fullName||editing.user?.email)}}</span><div><h3>Chỉnh sửa bảng lương</h3><p>{{editing.user?.fullName||editing.user?.email}} · Tháng {{monthLabel}}</p></div><button :disabled="saving" @click="editDialog=false"><v-icon icon="mdi-close"/></button></header>
        <v-card-text class="pr-edit-body">
          <section><h4><span>1</span>Lương và ngày công</h4><div class="pr-field-grid cols-3"><v-text-field v-model.number="form.baseSalary" type="number" label="Lương cơ bản" prefix="₫"/><v-text-field v-model.number="form.workDays" type="number" label="Ngày công"/><v-text-field v-model.number="form.workingDays" type="number" label="Công chuẩn"/></div></section>
          <section><h4><span>2</span>Tăng ca và thu nhập thêm</h4><div class="pr-field-grid cols-2"><v-text-field v-model.number="form.overtimeHours" type="number" label="Tăng ca thường (150%)" suffix="giờ"/><v-text-field v-model.number="form.overtimeSundayHours" type="number" label="Tăng ca Chủ nhật (200%)" suffix="giờ"/><v-text-field v-model.number="form.kpiAmount" type="number" label="Thưởng KPI" prefix="₫"/><v-text-field v-model.number="form.allowanceAmount" type="number" label="Phụ cấp" prefix="₫"/></div></section>
          <section><h4><span>3</span>Khấu trừ</h4><div class="pr-field-grid cols-2"><v-text-field v-model.number="form.advanceAmount" type="number" label="Tạm ứng" prefix="₫"/><v-text-field v-model.number="form.fillOrderAmount" type="number" label="Đền đơn" prefix="₫"/></div><v-switch v-model="form.hasInsurance" color="primary" hide-details inset label="Nhân viên tham gia BHXH, BHYT và BHTN"/></section>
          <section><h4><span>4</span>Kết quả (admin có thể ghi đè)</h4><div class="pr-field-grid cols-2"><v-text-field v-model.number="form.thanhTien" type="number" label="Lương theo công" prefix="₫" :hint="`Tự tính: ${formatVnd(preview.thanhTien)}`" persistent-hint/><v-text-field v-model.number="form.overtimeAmount" type="number" label="Tiền tăng ca" prefix="₫" :hint="`Tự tính: ${formatVnd(preview.overtimeAmount)}`" persistent-hint/><v-text-field v-model.number="form.totalSalary" type="number" label="Tổng thu nhập" prefix="₫" :hint="`Tự tính: ${formatVnd(preview.totalSalary)}`" persistent-hint/><v-text-field v-model.number="form.netSalary" type="number" label="Thực nhận" prefix="₫" :hint="`Tự tính: ${formatVnd(preview.netSalary)}`" persistent-hint color="success"/></div></section>
        </v-card-text>
        <v-card-actions class="pr-edit-footer"><v-btn variant="outlined" :disabled="saving" @click="editDialog=false">Huỷ</v-btn><v-btn color="primary" prepend-icon="mdi-content-save-outline" :loading="saving" @click="save">Lưu bảng lương</v-btn></v-card-actions>
      </v-card>
    </v-dialog>
    <PayslipModal v-model="slipDialog" :record="slipRecord" :name="slipName" :period="period"/>
  </div>
</template>

<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import ExcelJS from'exceljs';import{api}from'@/api';import{useToast}from'@/composables/use-toast';import{useAuthStore}from'@/stores/auth';import{formatVnd,currentPeriod}from'@/constants/hr';import PayslipModal from'./PayslipModal.vue';
const toast=useToast(),auth=useAuthStore(),canEdit=auth.canAccess('payroll','edit');const period=ref(currentPeriod()),rows=ref<any[]>([]),loading=ref(false),loadError=ref(''),search=ref(''),exporting=ref(false);const editDialog=ref(false),editing=ref<any>(),saving=ref(false),slipDialog=ref(false),slipRecord=ref<any>(),slipName=ref('');const form=reactive({baseSalary:0,workDays:0,workingDays:26,overtimeHours:0,overtimeSundayHours:0,kpiAmount:0,allowanceAmount:0,advanceAmount:0,fillOrderAmount:0,hasInsurance:false,thanhTien:0,overtimeAmount:0,totalSalary:0,netSalary:0});const monthLabel=computed(()=>{const[y,m]=period.value.split('-');return`${m}/${y}`});const filteredRows=computed(()=>{const q=search.value.trim().toLowerCase();return q?rows.value.filter(x=>`${x.user?.fullName||''} ${x.user?.email||''}`.toLowerCase().includes(q)):rows.value});function sum(key:string){return filteredRows.value.reduce((a,x)=>a+Number(x.record?.[key]||0),0)}function totalDeduction(r:any){return Number(r.advanceAmount||0)+Number(r.fillOrderAmount||0)+Number(r.insuranceAmount||0)}const totals=computed(()=>({baseSalary:sum('baseSalary'),workDays:sum('workDays'),thanhTien:sum('thanhTien'),overtimeHours:sum('overtimeHours'),overtimeSundayHours:sum('overtimeSundayHours'),overtimeAmount:sum('overtimeAmount'),kpiAmount:sum('kpiAmount'),allowanceAmount:sum('allowanceAmount'),totalSalary:sum('totalSalary'),deduction:filteredRows.value.reduce((a,x)=>a+totalDeduction(x.record),0),netSalary:sum('netSalary')}));const statItems=computed(()=>[{key:'base',label:'Tổng quỹ lương cơ bản',value:formatVnd(totals.value.baseSalary),icon:'mdi-file-document-dollar-outline',tone:'blue'},{key:'advance',label:'Tổng đã ứng',value:formatVnd(sum('advanceAmount')),icon:'mdi-wallet-outline',tone:'green'},{key:'deduct',label:'Tổng đền đơn',value:formatVnd(sum('fillOrderAmount')),icon:'mdi-package-variant-closed-remove',tone:'gold'},{key:'net',label:'Tổng thực nhận',value:formatVnd(totals.value.netSalary),icon:'mdi-cash-multiple',tone:'purple'},{key:'people',label:'Tổng nhân sự',value:`${filteredRows.value.length} người`,icon:'mdi-account-group-outline',tone:'slate'}]);function initials(n?:string){return n?n.trim().split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase():'?'}function workPercent(r:any){return Math.min(100,Math.round(Number(r.workDays||0)/Math.max(1,Number(r.workingDays||26))*100))}function moveMonth(delta:number){const[y,m]=period.value.split('-').map(Number),d=new Date(y,m-1+delta,1);period.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;load()}async function load(){loading.value=true;loadError.value='';try{const r=await api.get('/payroll',{params:{period:period.value}});rows.value=r.data.rows??[]}catch(e:any){rows.value=[];loadError.value=e?.response?.data?.hint||e?.response?.data?.error||'Vui lòng kiểm tra kết nối.'}finally{loading.value=false}}function viewSlip(i:any){slipRecord.value=i.record;slipName.value=i.user?.fullName||i.user?.email||'';slipDialog.value=true}function openEdit(i:any){editing.value=i;Object.assign(form,{baseSalary:i.record.baseSalary??0,workDays:i.record.workDays??0,workingDays:i.record.workingDays??26,overtimeHours:i.record.overtimeHours??0,overtimeSundayHours:i.record.overtimeSundayHours??0,kpiAmount:i.record.kpiAmount??0,allowanceAmount:i.record.allowanceAmount??0,advanceAmount:i.record.advanceAmount??0,fillOrderAmount:i.record.fillOrderAmount??0,hasInsurance:!!i.record.hasInsurance,thanhTien:i.record.thanhTien??0,overtimeAmount:i.record.overtimeAmount??0,totalSalary:i.record.totalSalary??0,netSalary:i.record.netSalary??0});editDialog.value=true}const preview=computed(()=>{const working=Math.max(1,Number(form.workingDays||26)),thanhTien=Math.round(Number(form.baseSalary||0)*Number(form.workDays||0)/working),overtimeAmount=Math.round(Number(form.baseSalary||0)/208*(Number(form.overtimeHours||0)*1.5+Number(form.overtimeSundayHours||0)*2)),insurance=form.hasInsurance?598500:0,totalSalary=thanhTien+overtimeAmount+Number(form.kpiAmount||0)+Number(form.allowanceAmount||0);return{thanhTien,overtimeAmount,totalSalary,netSalary:totalSalary-Number(form.advanceAmount||0)-Number(form.fillOrderAmount||0)-insurance}});async function save(){saving.value=true;try{await api.put(`/payroll/${editing.value.user.id}`,{...form},{params:{period:period.value}});toast.success('Đã lưu phiếu lương');editDialog.value=false;await load()}catch(e:any){toast.error(e?.response?.data?.hint||e?.response?.data?.error||'Lưu thất bại')}finally{saving.value=false}}async function exportExcel(){exporting.value=true;try{const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet(`T${monthLabel.value.replace('/','-')}`);ws.addRow(['#','Nhân viên','Email','Lương cơ bản','Ngày công','Công chuẩn','Lương theo công','Tăng ca thường','Tăng ca CN','Tiền tăng ca','KPI','Phụ cấp','Tổng thu nhập','Tạm ứng','Đền đơn','Bảo hiểm','Thực nhận']);filteredRows.value.forEach((x,i)=>ws.addRow([i+1,x.user?.fullName,x.user?.email,x.record.baseSalary,x.record.workDays,x.record.workingDays,x.record.thanhTien,x.record.overtimeHours,x.record.overtimeSundayHours,x.record.overtimeAmount,x.record.kpiAmount,x.record.allowanceAmount,x.record.totalSalary,x.record.advanceAmount,x.record.fillOrderAmount,x.record.insuranceAmount,x.record.netSalary]));ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF2F80ED'}};ws.columns.forEach(c=>c.width=16);ws.getColumn(2).width=24;ws.getColumn(3).width=28;const buffer=await wb.xlsx.writeBuffer(),blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bang-luong-${period.value}.xlsx`;a.click();URL.revokeObjectURL(url)}catch{toast.error('Không thể xuất Excel')}finally{exporting.value=false}}onMounted(load);
</script>

